def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in b_intervals:
        if b_merged and start <= b_merged[-1][1]:
            # Overlapping or touching, merge
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []

    for a_start, a_end in a_intervals:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for c_start, c_end in current_ranges:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    new_ranges.append([c_start, c_end])
                else:
                    # There is overlap, keep the parts outside b
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    if c_end > b_end:
                        new_ranges.append([b_end, c_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching/overlapping intervals in result
    if not result:
        return []

    result.sort()
    merged = [result[0]]

    for start, end in result[1:]:
        if start <= merged[-1][1]:
            # Overlapping or touching, merge
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

